-- StockPilot AI production Oracle schema
CREATE TABLE roles (role_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, role_name VARCHAR2(30) UNIQUE NOT NULL);
CREATE TABLE users (user_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, role_id NUMBER NOT NULL REFERENCES roles(role_id), full_name VARCHAR2(120) NOT NULL, email VARCHAR2(160) UNIQUE NOT NULL, password_hash VARCHAR2(255) NOT NULL, active CHAR(1) DEFAULT 'Y' CHECK(active IN ('Y','N')));
CREATE TABLE categories (category_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category_name VARCHAR2(100) UNIQUE NOT NULL);
CREATE TABLE suppliers (supplier_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, supplier_name VARCHAR2(150) NOT NULL, contact_phone VARCHAR2(40), email VARCHAR2(160), lead_time_days NUMBER(5) DEFAULT 4 CHECK(lead_time_days >= 0), reliability_score NUMBER(5,4) CHECK(reliability_score BETWEEN 0 AND 1));
CREATE TABLE products (product_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category_id NUMBER NOT NULL REFERENCES categories(category_id), supplier_id NUMBER REFERENCES suppliers(supplier_id), sku VARCHAR2(40) UNIQUE NOT NULL, barcode VARCHAR2(60) UNIQUE NOT NULL, product_name VARCHAR2(180) NOT NULL, purchase_cost NUMBER(12,2) CHECK(purchase_cost >= 0), selling_price NUMBER(12,2) CHECK(selling_price >= 0), current_qty NUMBER(12) DEFAULT 0 CHECK(current_qty >= 0), minimum_stock NUMBER(12) DEFAULT 0 CHECK(minimum_stock >= 0), reorder_level NUMBER(12) DEFAULT 0 CHECK(reorder_level >= 0), expiry_required CHAR(1) DEFAULT 'N' CHECK(expiry_required IN ('Y','N')), active CHAR(1) DEFAULT 'Y' CHECK(active IN ('Y','N')));
CREATE TABLE product_suppliers (product_id NUMBER REFERENCES products(product_id), supplier_id NUMBER REFERENCES suppliers(supplier_id), supplier_cost NUMBER(12,2) CHECK(supplier_cost >= 0), preferred_flag CHAR(1) DEFAULT 'N' CHECK(preferred_flag IN ('Y','N')), CONSTRAINT pk_product_suppliers PRIMARY KEY(product_id,supplier_id));
CREATE TABLE stock_batches (batch_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, product_id NUMBER NOT NULL REFERENCES products(product_id), batch_code VARCHAR2(80) UNIQUE NOT NULL, quantity NUMBER(12) CHECK(quantity >= 0), expiry_date DATE, received_date DATE NOT NULL);
CREATE TABLE sales (sale_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, invoice_no VARCHAR2(50) UNIQUE NOT NULL, sale_date TIMESTAMP NOT NULL, subtotal NUMBER(12,2), discount NUMBER(12,2) DEFAULT 0, tax NUMBER(12,2) DEFAULT 0, total NUMBER(12,2), payment_method VARCHAR2(30), status VARCHAR2(20), user_id NUMBER REFERENCES users(user_id));
CREATE TABLE sale_items (sale_item_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, sale_id NUMBER REFERENCES sales(sale_id), product_id NUMBER REFERENCES products(product_id), quantity NUMBER(12) CHECK(quantity > 0), unit_price NUMBER(12,2), cost_price NUMBER(12,2));
CREATE TABLE purchase_orders (po_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, supplier_id NUMBER REFERENCES suppliers(supplier_id), po_number VARCHAR2(50) UNIQUE NOT NULL, order_date DATE NOT NULL, expected_date DATE, status VARCHAR2(20) NOT NULL, total NUMBER(12,2));
CREATE TABLE purchase_order_items (po_item_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, po_id NUMBER REFERENCES purchase_orders(po_id), product_id NUMBER REFERENCES products(product_id), ordered_qty NUMBER(12) CHECK(ordered_qty > 0), received_qty NUMBER(12) DEFAULT 0 CHECK(received_qty >= 0), unit_cost NUMBER(12,2));
CREATE TABLE stock_movements (movement_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, product_id NUMBER REFERENCES products(product_id), batch_id NUMBER REFERENCES stock_batches(batch_id), movement_type VARCHAR2(30) NOT NULL, quantity NUMBER(12) NOT NULL, reason VARCHAR2(300), reference_no VARCHAR2(80), created_at TIMESTAMP DEFAULT SYSTIMESTAMP, user_id NUMBER REFERENCES users(user_id));
CREATE TABLE notifications (notification_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, kind VARCHAR2(30), title VARCHAR2(200), message VARCHAR2(500), severity VARCHAR2(20), is_read CHAR(1) DEFAULT 'N', created_at TIMESTAMP DEFAULT SYSTIMESTAMP);
CREATE TABLE audit_logs (audit_id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, action_name VARCHAR2(80), entity_name VARCHAR2(80), entity_id NUMBER, detail VARCHAR2(1000), created_at TIMESTAMP DEFAULT SYSTIMESTAMP, user_id NUMBER REFERENCES users(user_id));
CREATE TABLE inventory_policies (policy_key VARCHAR2(80) PRIMARY KEY, policy_value VARCHAR2(120) NOT NULL);
CREATE INDEX idx_products_category ON products(category_id); CREATE INDEX idx_batches_expiry ON stock_batches(expiry_date); CREATE INDEX idx_movements_product_date ON stock_movements(product_id,created_at); CREATE INDEX idx_sales_date ON sales(sale_date);
